    --bg-color: #f9f9fb;
    --card-bg: #ffffff;
    --border-color: #e0e0e0;
    --focus-ring: rgba(0, 102, 204, 0.25);
    --error-color: #d32f2f;
    --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
}

* {
    box-sizing: border-box;
}

body {
    font-family: var(--font-family);
    background-color: var(--bg-color);
    color: var(--text-color);
    line-height: 1.5;
    margin: 0;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
}

.container {
    width: 100%;
    max-width: 480px;
    padding: 2rem;
}

.support-card {
    background: var(--card-bg);
    padding: 2.5rem;
    border-radius: 12px;
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

h1 {
    font-size: 1.75rem;
    font-weight: 700;
    margin: 0 0 0.5rem 0;
}

.subtitle {
    color: var(--text-muted);
    margin-bottom: 2rem;
}

.contact-form {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.form-field {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

label {
    font-weight: 600;
    font-size: 0.875rem;
}

.required-star {
    color: var(--error-color);
    margin-left: 2px;
}

input {
    padding: 0.75rem;
    border: 1px solid var(--border-color);
    border-radius: 6px;
    font-size: 1rem;
    font-family: inherit;
    transition: border-color 0.2s, box-shadow 0.2s;
}

input:focus {
    outline: none;
    border-color: var(--primary-color);
    box-shadow: 0 0 0 3px var(--focus-ring);
}

.helper-text {
    font-size: 0.75rem;
    color: var(--text-muted);
}

.error-message {
    font-size: 0.75rem;
    color: var(--error-color);
    margin-top: -0.25rem;
}

.submit-button {
    background-color: var(--primary-color);
    color: white;
    border: none;
    padding: 0.875rem;
    border-radius: 6px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: background-color 0.2s;
    margin-top: 0.5rem;
}

.submit-button:hover {
    background-color: var(--primary-hover);
}

.submit-button:focus {
    outline: none;
    box-shadow: 0 0 0 3px var(--focus-ring);
}

@media (max-width: 480px) {
    .container {
        padding: 1rem;
    }

    .support-card {
        padding: 1.5rem;
        border-radius: 0;
        box-shadow: none;
    }
}
