const FormField = ({ label, id, type = "text", required, autocomplete, helperText, error, value, onChange }) => {
    const helperId = `${id}-helper`;
    const errorId = `${id}-error`;
    const describedBy = [
        helperText ? helperId : null,
        error ? errorId : null
    ].filter(Boolean).join(' ');

    return (
        <div className="form-field">
            <label htmlFor={id}>
                {label}
                {required && <span className="required-star" aria-hidden="true">*</span>}
            </label>
            <input
                id={id}
                name={id}
                type={type}
                required={required}
                autoComplete={autocomplete}
                value={value}
                onChange={onChange}
                aria-describedby={describedBy || undefined}
                aria-invalid={!!error}
            />
            {helperText && (
                <span id={helperId} className="helper-text">
                    {helperText}
                </span>
            )}
            {error && (
                <span id={errorId} className="error-message">
                    Error: {error}
                </span>
            )}
        </div>
    );
};

const ContactForm = () => {
    const [formData, setFormData] = useState({
        fullName: '',
        email: '',
        phone: ''
    });
    const [errors, setErrors] = useState({});
    const [submitted, setSubmitted] = useState(false);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
        // Clear error when user starts typing
        if (errors[name]) {
            setErrors(prev => {
                const newErrors = { ...prev };
                delete newErrors[name];
                return newErrors;
            });
        }
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        const newErrors = {};

        if (!formData.fullName.trim()) {
            newErrors.fullName = "Full name is required";
        }
        if (!formData.email.trim()) {
            newErrors.email = "Email address is required";
        } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
            newErrors.email = "Please enter a valid email address";
        }

        if (Object.keys(newErrors).length > 0) {
            setErrors(newErrors);
            // Focus first error field
            const firstErrorField = Object.keys(newErrors)[0];
            document.getElementById(firstErrorField)?.focus();
        } else {
            setSubmitted(true);
            console.log("Form submitted:", formData);
        }
    };

    if (submitted) {
        return (
            <div className="success-message" role="alert">
                <h2>Thank you!</h2>
                <p>Your request has been received. We'll get back to you soon.</p>
                <button 
                    className="submit-button" 
                    onClick={() => {
                        setSubmitted(false);
                        setFormData({ fullName: '', email: '', phone: '' });
                    }}
                >
                    Send another message
                </button>
            </div>
        );
    }

    return (
        <form className="contact-form" onSubmit={handleSubmit} noValidate>
            <FormField
                label="Full name"
                id="fullName"
                autocomplete="name"
                required
                value={formData.fullName}
                onChange={handleChange}
                error={errors.fullName}
            />
            <FormField
                label="Email address"
                id="email"
                type="email"
                autocomplete="email"
                required
                value={formData.email}
                onChange={handleChange}
                error={errors.email}
            />
            <FormField
                label="Phone number (optional)"
                id="phone"
                type="tel"
                autocomplete="tel"
                helperText="Format: (555) 555-5555"
                value={formData.phone}
                onChange={handleChange}
            />
            <button type="submit" className="submit-button">
                Send message
            </button>
        </form>
    );
};

const App = () => {
    return (
        <main className="container">
            <div className="support-card">
                <h1>Contact Support</h1>
                <p className="subtitle">Tell us about your issue and we'll help you out.</p>
                <ContactForm />
            </div>
        </main>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
