+const { chromium } = require('playwright');
+const fs = require('fs');
+const path = require('path');
+
+async function runA11yTest() {
+    let browser;
+    try {
+        browser = await chromium.launch();
+        const context = await browser.newContext();
+        const page = await context.newPage();
+        
+        // Load the local index.html
+        const filePath = `file://${path.resolve('index.html')}`;
+        await page.goto(filePath, { waitUntil: 'networkidle' });
+        
+        // Inject axe-core
+        await page.addScriptTag({ path: '/tmp/axe.min.js' });
+        
+        // Run axe
+        const results = await page.evaluate(async () => {
+            // Need to wait for Babel to transpile and React to render
+            // Since script.js is type="text/babel", it's async.
+            // We'll wait for #root to have content.
+            const wait = (ms) => new Promise(resolve => setTimeout(resolve, ms));
+            let retries = 50;
+            while (retries > 0 && document.getElementById('root').innerHTML === '') {
+                await wait(100);
+                retries--;
+            }
+            return await window.axe.run();
+        });
+        
+        const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
+        const bp = results.violations.filter(v => v.tags.includes('best-practice'));
+        
+        console.log(JSON.stringify({
+            wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
+            bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
+        }, null, 2));
+        
+        process.exit(wcag.length > 0 ? 1 : 0);
+    } catch (error) {
+        console.error('Error running test:', error);
+        process.exit(1);
+    } finally {
+        if (browser) await browser.close();
+    }
+}
+
+runA11yTest();
+
